// cold (blue) -> hot (pink) — perceptually simple two-stop lerp with mid gold
function heat(v, lo, hi) {
  const f = Math.max(0, Math.min(1, (v - lo) / (hi - lo)));
  const stops = [[79,163,255],[232,194,74],[255,45,120]];
  const seg = f < 0.5 ? 0 : 1, sf = (f - seg*0.5) * 2;
  const a = stops[seg], b = stops[seg+1];
  return `rgb(${Math.round(a[0]+(b[0]-a[0])*sf)},${Math.round(a[1]+(b[1]-a[1])*sf)},${Math.round(a[2]+(b[2]-a[2])*sf)})`;
}

